import{_ as e,H as t,f as B,i as A}from"./chunks/framework.BH2BK_3i.js";const l=JSON.parse('{"title":"第十四封信-“必须拥有一支50mm镜头的十大理由”","description":"","frontmatter":{},"headers":[],"relativePath":"去无方向的信/第十四封信-“必须拥有一支50mm镜头的十大理由”.md","filePath":"去无方向的信/第十四封信-“必须拥有一支50mm镜头的十大理由”.md","lastUpdated":1795542896000}'),i={name:"去无方向的信/第十四封信-“必须拥有一支50mm镜头的十大理由”.md"};function a(s,E,m,n,r,p){return t(),B("div",null,[...E[0]||(E[0]=[A('<h1 id="第十四封信-必须拥有一支50mm镜头的十大理由" tabindex="-1">第十四封信-“必须拥有一支50mm镜头的十大理由” <a class="header-anchor" href="#第十四封信-必须拥有一支50mm镜头的十大理由" aria-label="Permalink to &quot;第十四封信-“必须拥有一支50mm镜头的十大理由”&quot;">​</a></h1><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E5%259B%259B%25E5%25B0%2581%25E4%25BF%25A1-%25E2%2580%259C%25E5%25BF%2585%25E9%25A1%25BB%25E6%258B%25A5%25E6%259C%2589%25E4%25B8%2580%25E6%2594%25AF50mm%25E9%2595%259C%25E5%25A4%25B4%25E7%259A%2584%25E5%258D%2581%25E5%25A4%25A7%25E7%2590%2586%25E7%2594%25B1%25E2%2580%259D/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E5%259B%259B%25E5%25B0%2581%25E4%25BF%25A1-%25E2%2580%259C%25E5%25BF%2585%25E9%25A1%25BB%25E6%258B%25A5%25E6%259C%2589%25E4%25B8%2580%25E6%2594%25AF50mm%25E9%2595%259C%25E5%25A4%25B4%25E7%259A%2584%25E5%258D%2581%25E5%25A4%25A7%25E7%2590%2586%25E7%2594%25B1%25E2%2580%259D/1.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E5%259B%259B%25E5%25B0%2581%25E4%25BF%25A1-%25E2%2580%259C%25E5%25BF%2585%25E9%25A1%25BB%25E6%258B%25A5%25E6%259C%2589%25E4%25B8%2580%25E6%2594%25AF50mm%25E9%2595%259C%25E5%25A4%25B4%25E7%259A%2584%25E5%258D%2581%25E5%25A4%25A7%25E7%2590%2586%25E7%2594%25B1%25E2%2580%259D/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E5%259B%259B%25E5%25B0%2581%25E4%25BF%25A1-%25E2%2580%259C%25E5%25BF%2585%25E9%25A1%25BB%25E6%258B%25A5%25E6%259C%2589%25E4%25B8%2580%25E6%2594%25AF50mm%25E9%2595%259C%25E5%25A4%25B4%25E7%259A%2584%25E5%258D%2581%25E5%25A4%25A7%25E7%2590%2586%25E7%2594%25B1%25E2%2580%259D/2.png" alt=""></a></p><p>生生：</p><p>你好哇。</p><p>上次我说我在网上查到一篇文章，文章标题是“必须拥有一支 50mm 镜头的十大理由”，光是标题就把我看懵了，哈哈哈！我不认为 50mm 镜头是必须要有的一枚镜头，更不要说“十大理由”了……如果非要给选择 50mm 镜头找一个理由，那我能想到的，有且只有一个：你是一个喜欢游离于人群之外的控制狂。</p><p>其实不管用什么镜头，学会控制画面都是必须的，但 50mm 镜头是控场之王。</p><p>我们先来看看喜欢用 50mm 镜头的人说的话：</p><ul><li><p>&quot; It is an illusion that photos are made with the camera…they are made with the eye, heartand head. &quot; —— Henri Cartier-Bresson“说照片儿是相机拍的的人肯定是得了什么疯症……照片儿是用眼睛拍的，用心灵拍的，用脑子拍的。” —— 亨利·卡蒂埃 - 布列松</p></li><li><p>&quot; Rather than a profession, photography has always been a passion for me, a passioncloser to an obsession. &quot; —— Marc Riboud“摄影对我来说不能全算是职业，更多的还是热情吧，一种近乎强迫症的痴迷。” —— 马克·吕布</p></li><li><p>&quot; I think of photography like therapy.&quot; —— Harry Gruyaert“我觉得摄影能治病。” —— 哈利·格鲁亚特</p></li></ul><p>你看，都是病人。</p><p>咱们再来瞧瞧这三位拍的照片儿。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E5%259B%259B%25E5%25B0%2581%25E4%25BF%25A1-%25E2%2580%259C%25E5%25BF%2585%25E9%25A1%25BB%25E6%258B%25A5%25E6%259C%2589%25E4%25B8%2580%25E6%2594%25AF50mm%25E9%2595%259C%25E5%25A4%25B4%25E7%259A%2584%25E5%258D%2581%25E5%25A4%25A7%25E7%2590%2586%25E7%2594%25B1%25E2%2580%259D/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E5%259B%259B%25E5%25B0%2581%25E4%25BF%25A1-%25E2%2580%259C%25E5%25BF%2585%25E9%25A1%25BB%25E6%258B%25A5%25E6%259C%2589%25E4%25B8%2580%25E6%2594%25AF50mm%25E9%2595%259C%25E5%25A4%25B4%25E7%259A%2584%25E5%258D%2581%25E5%25A4%25A7%25E7%2590%2586%25E7%2594%25B1%25E2%2580%259D/3.png" alt=""></a></p><ul><li>Henri Cartier-Bresson</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E5%259B%259B%25E5%25B0%2581%25E4%25BF%25A1-%25E2%2580%259C%25E5%25BF%2585%25E9%25A1%25BB%25E6%258B%25A5%25E6%259C%2589%25E4%25B8%2580%25E6%2594%25AF50mm%25E9%2595%259C%25E5%25A4%25B4%25E7%259A%2584%25E5%258D%2581%25E5%25A4%25A7%25E7%2590%2586%25E7%2594%25B1%25E2%2580%259D/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E5%259B%259B%25E5%25B0%2581%25E4%25BF%25A1-%25E2%2580%259C%25E5%25BF%2585%25E9%25A1%25BB%25E6%258B%25A5%25E6%259C%2589%25E4%25B8%2580%25E6%2594%25AF50mm%25E9%2595%259C%25E5%25A4%25B4%25E7%259A%2584%25E5%258D%2581%25E5%25A4%25A7%25E7%2590%2586%25E7%2594%25B1%25E2%2580%259D/4.png" alt=""></a></p><ul><li>Marc Riboud</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E5%259B%259B%25E5%25B0%2581%25E4%25BF%25A1-%25E2%2580%259C%25E5%25BF%2585%25E9%25A1%25BB%25E6%258B%25A5%25E6%259C%2589%25E4%25B8%2580%25E6%2594%25AF50mm%25E9%2595%259C%25E5%25A4%25B4%25E7%259A%2584%25E5%258D%2581%25E5%25A4%25A7%25E7%2590%2586%25E7%2594%25B1%25E2%2580%259D/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E5%259B%259B%25E5%25B0%2581%25E4%25BF%25A1-%25E2%2580%259C%25E5%25BF%2585%25E9%25A1%25BB%25E6%258B%25A5%25E6%259C%2589%25E4%25B8%2580%25E6%2594%25AF50mm%25E9%2595%259C%25E5%25A4%25B4%25E7%259A%2584%25E5%258D%2581%25E5%25A4%25A7%25E7%2590%2586%25E7%2594%25B1%25E2%2580%259D/5.png" alt=""></a></p><ul><li>Harry Gruyaert</li></ul><p>不知道你还记不记得上次看过的那些 35mm 镜头拍的照片儿，完全不一样了，是吧，太规矩了。就像我刚说过的，选择 50mm 镜头，有且只有一个原因，那就是摄影师是控制狂。</p><p>50mm 镜头的视角比 35mm 镜头的窄一些，但论收紧画面、压缩画面、控制画面的能力，在日常中，远胜于 35mm。因为在日常中，我们身边的环境大都比较局促，所以尤其显得 50mm这个焦段特别紧凑。</p><p>而正是因为这个紧凑，所以好多人都用 50mm 镜头拍人像，离得近一点，光圈开得大一点，当个小长焦用。但我们看那些特别厉害的摄影师，他们用 50mm 镜头，却很少见他们把这个焦段当做小长焦来用，反而，他们把 50mm 用成了 35mm，甚至 28mm。</p><p>你说他们也挺奇怪的，那为什么不直接用 28mm 镜头呢？</p><p>这时候，就又可以引入一个新概念了：长焦拍大景，广角拍小景。</p><p>这个概念最早我是听我老师说的，当时我在亲手去试之前貌似就有点懂了，因为我小时候练过一小小段时间书法，书法里有个概念叫“大字难于结密而无间，小字难于宽绰而有余”。基本上是同一个内核，字面上看起来好像有点矛盾，但其实很是真理。</p><p>正是因为长焦拍的大景只是“像广角”，广角拍的小景只是“像长焦”，所以这样拍，会给我们带来平时不常有的视觉体验。</p><p>那好，现在就又来了一个问题：怎么能让焦距较长的镜头拍出来的东西看起来像广角？或，怎么能让焦距较短的镜头拍出来的东西看起来像长焦？</p><p>距离，又是距离。</p><p>镜头越长，我们离得越应该远，镜头越短，我们离得越应该近。而不是像很多人一样，用长焦就生怕画面太开阔，用广角就生怕自己不能把整个宇宙都拍进一张照片儿里去。</p><p>于是，我们大概也知道了上面那三位愿意用 50mm 镜头的另外一个原因了，那就是他们都不想离人特别近……Marc Riboud 最早用 50mm 镜头，但看他的照片儿，明显能看出来他比Henri Cartier-Bresson 和 Harry Gruyaert 离人要近得多，所以后来他换镜头了，换成了35mm。</p><p>既然聊到这儿了，我就顺着这个话茬儿再多说两句。</p><p>我感觉，用 50mm 镜头的摄影师，尤其是搞 Documentary Photography（不准确地翻译为我们常说的“纪实摄影”）的那些人，他们不太在意他们镜头里的“人”，他们满世界寻找结构性的画面，他们能非常细腻地觉察颜色和光线，他们精彩极了，但是，他们没那么在意“人”，即便他们的绝大多数照片儿里都有人，但他们只把“人”当做画面中补位的元素。这没有是好是坏的评判，只是陈述事实。</p><p>看上面三张照片儿，只有 Marc Riboud 把人当人，所以后来他换镜头，大概是一个必然的结果。</p><p>最后，咱们再来看两张照片儿。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E5%259B%259B%25E5%25B0%2581%25E4%25BF%25A1-%25E2%2580%259C%25E5%25BF%2585%25E9%25A1%25BB%25E6%258B%25A5%25E6%259C%2589%25E4%25B8%2580%25E6%2594%25AF50mm%25E9%2595%259C%25E5%25A4%25B4%25E7%259A%2584%25E5%258D%2581%25E5%25A4%25A7%25E7%2590%2586%25E7%2594%25B1%25E2%2580%259D/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E5%259B%259B%25E5%25B0%2581%25E4%25BF%25A1-%25E2%2580%259C%25E5%25BF%2585%25E9%25A1%25BB%25E6%258B%25A5%25E6%259C%2589%25E4%25B8%2580%25E6%2594%25AF50mm%25E9%2595%259C%25E5%25A4%25B4%25E7%259A%2584%25E5%258D%2581%25E5%25A4%25A7%25E7%2590%2586%25E7%2594%25B1%25E2%2580%259D/6.png" alt=""></a></p><ul><li>Harry Gruyaert</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E5%259B%259B%25E5%25B0%2581%25E4%25BF%25A1-%25E2%2580%259C%25E5%25BF%2585%25E9%25A1%25BB%25E6%258B%25A5%25E6%259C%2589%25E4%25B8%2580%25E6%2594%25AF50mm%25E9%2595%259C%25E5%25A4%25B4%25E7%259A%2584%25E5%258D%2581%25E5%25A4%25A7%25E7%2590%2586%25E7%2594%25B1%25E2%2580%259D/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E5%259B%259B%25E5%25B0%2581%25E4%25BF%25A1-%25E2%2580%259C%25E5%25BF%2585%25E9%25A1%25BB%25E6%258B%25A5%25E6%259C%2589%25E4%25B8%2580%25E6%2594%25AF50mm%25E9%2595%259C%25E5%25A4%25B4%25E7%259A%2584%25E5%258D%2581%25E5%25A4%25A7%25E7%2590%2586%25E7%2594%25B1%25E2%2580%259D/7.png" alt=""></a></p><ul><li>Bruce Gilden</li></ul><p>上面一张是 Harry Gruyaert 用 50mm 镜头拍的，下面一张是 Bruce Gilden 用 28mm 镜头拍的……都非常精彩，但如果只陈述事实的话，我粗浅地认为，BG 比 HG 更在意他拍到的人。</p><p>我之前很喜欢街拍，后来就越来越不拍了，因为我感受不太到人心和人心的那种联结，就很没劲，我可以找到结构性的画面，我可以试着去觉察颜色和光线，我可以把路上的人当做我画面里补位的元素，我可以模仿现在各大摄影营销号特别爱发的、大家也特别爱看的那种“街头摄影”，或“街头光影摄影”，或“街头色彩摄影”，但我总觉得好像哪儿不太对。</p><p>至于“人间烟火气”的那种扫街，我就更不喜欢了。</p><p>所以，我现在只拍我认识的人，只拍我在意的人，于是，不知道是不是真的有这种冥冥之中的规律，我现在最心爱的焦段是 28mm。</p><p>咱们下回，可得好好儿地聊聊这个焦段。</p>',41)])])}const h=e(i,[["render",a]]);export{l as __pageData,h as default};
